import * as verificationFs from 'node:fs';
import {createHash as verificationHash} from 'node:crypto';
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, mkdtempSync, rmSync, readdirSync, mkdirSync, cpSync } from 'node:fs';
import { execFileSync as rawExecFileSync, spawnSync as rawSpawnSync } from 'node:child_process';
import { tmpdir } from 'node:os';
import path from 'node:path';
const VERIFICATION_LABEL='manager-preview';

// Contributor verification only. Opt-in capture retains existing observations
// before disposable fixture cleanup; it never changes a product input/oracle.
const verificationRoot=process.env.PGB81_EVIDENCE_DIR;let verificationSequence=0;
if(verificationRoot)assert(path.isAbsolute(verificationRoot),'Use an absolute external verification directory.');
const verificationSHA=bytes=>verificationHash('sha256').update(bytes).digest('hex');
function verificationBlob(bytes){if(!verificationRoot)return null;const hash=verificationSHA(bytes),dir=path.join(verificationRoot,'blobs');verificationFs.mkdirSync(dir,{recursive:true});const file=path.join(dir,hash);try{verificationFs.writeFileSync(file,bytes,{flag:'wx'});}catch(e){if(e.code!=='EEXIST')throw e;}return {sha256:hash,bytes:Buffer.byteLength(bytes),file};}
function verificationRecord(kind,value){if(!verificationRoot)return;assert(path.isAbsolute(verificationRoot),'Use an absolute external verification directory.');const dir=path.join(verificationRoot,VERIFICATION_LABEL);verificationFs.mkdirSync(dir,{recursive:true});verificationFs.writeFileSync(path.join(dir,String(verificationSequence++).padStart(6,'0')+'-'+kind+'.json'),JSON.stringify(value,null,2)+'\n');}
function verificationFiles(args,cwd){if(!verificationRoot)return null;const result=[];for(const flag of ['--config','--input','--context']){const i=args.indexOf(flag);if(i<0||!args[i+1])continue;const argument=args[i+1],file=path.resolve(cwd??process.cwd(),argument);try{const st=verificationFs.statSync(file);result.push({flag,path:file,kind:st.isFile()?'file':'other',content:st.isFile()?verificationBlob(verificationFs.readFileSync(file)):null});}catch(e){result.push({flag,path:file,state:e.code??'unreadable'});}}return result;}
function verificationInventory(cwd){if(!verificationRoot)return null;const dir=cwd??process.cwd();return verificationFs.readdirSync(dir,{withFileTypes:true}).map(e=>{const p=path.join(dir,e.name);return {name:e.name,kind:e.isFile()?'file':e.isDirectory()?'directory':'other',sha256:e.isFile()?verificationSHA(verificationFs.readFileSync(p)):null};}).sort((a,b)=>a.name.localeCompare(b.name));}
function spawnSync(file,args=[],options={}){if(!verificationRoot||file!==process.execPath)return rawSpawnSync(file,args,options);const before={inputs:verificationFiles(args,options.cwd),inventory:verificationInventory(options.cwd)},r=rawSpawnSync(file,args,options);verificationRecord('child',{file,args,cwd:options.cwd??process.cwd(),status:r.status,signal:r.signal,error:r.error?.message??null,stdout:r.stdout?.toString()??'',stderr:r.stderr?.toString()??'',before,after:{inputs:verificationFiles(args,options.cwd),inventory:verificationInventory(options.cwd)}});return r;}
function execFileSync(file,args=[],options={}){if(!verificationRoot||file!==process.execPath)return rawExecFileSync(file,args,options);const before={inputs:verificationFiles(args,options.cwd),inventory:verificationInventory(options.cwd)};try{const r=rawExecFileSync(file,args,options);verificationRecord('child',{file,args,cwd:options.cwd??process.cwd(),status:0,stdout:r?.toString()??'',stderr:'',before,after:{inputs:verificationFiles(args,options.cwd),inventory:verificationInventory(options.cwd)}});return r;}catch(e){verificationRecord('child',{file,args,cwd:options.cwd??process.cwd(),status:e.status??null,signal:e.signal??null,stdout:e.stdout?.toString()??'',stderr:e.stderr?.toString()??'',before,after:{inputs:verificationFiles(args,options.cwd),inventory:verificationInventory(options.cwd)}});throw e;}}
function verificationAPI(c,config,snapshot,actual){if(!verificationRoot)return;verificationRecord('api',{case_id:c.id??null,config:verificationBlob(config),snapshot:verificationBlob(snapshot),options_present:Object.hasOwn(c,'options'),options:c.options??{},actual});}

import canonicalize from 'canonicalize';
import { createHash } from 'node:crypto';
import { previewSnapshot } from '../lib/manager/decisions.mjs';
import { SNAPSHOT_LIMITS, composeOrdinarySnapshot } from '../lib/manager/snapshot.mjs';
import { inspectManagerHistory, inspectRecordedCompletion } from '../lib/contracts/receipts.mjs';
const fixtures=JSON.parse(readFileSync(new URL('./fixtures/manager-candidates.json',import.meta.url))).cases;
const repairPacket=JSON.parse(readFileSync(new URL('./fixtures/manager-repairs.json',import.meta.url))),compatibility=repairPacket.inherited_current_preview;
const legacyFullById=new Map(repairPacket.legacy_native_full.cases.map(c=>[c.id,c.expected]));
const fresh=id=>structuredClone(fixtures.find(c=>c.id===id));
const run=c=>{const config=JSON.stringify(c.config),snapshot=JSON.stringify(c.snapshot),actual=previewSnapshot(config,snapshot,c.options);verificationAPI(c,config,snapshot,actual);return actual;};
const codes=r=>r.streams.flatMap(s=>s.reasons.map(r=>r.code));
const selected=r=>r.streams.filter(s=>s.decision==='select').map(s=>s.selected_ticket_id);
for(const fixture of fixtures)test(`frozen scenario ${fixture.id}`,()=>{const before=JSON.stringify(fixture),r=run(fixture);assert.equal(r.valid,true,JSON.stringify(r));assert.equal(r.streams.length,fixture.expected.streams.length);assert.deepEqual(selected(r),fixture.expected.streams.filter(e=>e.decision==='select').map(e=>e.selected_ticket_id));for(const e of fixture.expected.streams){const s=r.streams.find(s=>s.scope.project_id===e.project_id&&s.scope.label===e.label);assert.ok(s);assert.equal(s.decision,e.decision);assert.equal(s.selected_ticket_id,e.selected_ticket_id);assert.equal(s.return_count,e.return_count);for(const d of e.reason_details??[])assert.ok(s.reasons.some(r=>r.code===d.code&&r.path===d.path),fixture.id+' '+JSON.stringify(d));if(e.reason)assert.ok(s.reasons.some(r=>r.code===e.reason),JSON.stringify(s));if(fixture.id.startsWith('membership-')){assert.deepEqual(s.scope,{site:fixture.snapshot.site,project_id:e.project_id,label:e.label});for(const field of ['occupied_ids','blocked_ids','human_review_ids','counts_complete'])if(Object.hasOwn(e,field))assert.deepEqual(s[field],e[field],fixture.id+' '+field);for(const code of e.reasons??[])assert.ok(s.reasons.some(r=>r.code===code),fixture.id+' '+code);for(const code of e.absent_reasons??[])assert.ok(!s.reasons.some(r=>r.code===code),fixture.id+' '+code);if(e.mismatch_path)assert.ok(s.reasons.some(r=>r.code==='MEMBERSHIP_MISMATCH'&&r.path===e.mismatch_path),fixture.id);} }assert.equal(JSON.stringify(fixture),before);assert.deepEqual(run(fixture),r);assert.equal(r.writes,0);assert.equal(r.execution_authorized,false);if(legacyFullById.has(fixture.id))assert.deepEqual(JSON.parse(JSON.stringify(r)),legacyFullById.get(fixture.id),fixture.id+' full native oracle');});
test('exact expected digest covers configuration and every snapshot field',()=>{const c=fresh('S01'),r=run(c);assert.equal(r.snapshot_digest,'sha256:'+createHash('sha256').update(canonicalize({configuration_digest:r.configuration_digest,snapshot:c.snapshot})).digest('hex'));c.options={expectedSnapshotDigest:r.snapshot_digest};assert.equal(run(c).status,'complete');for(const mutate of [c=>c.config.projects[0].key='RENAMED',c=>c.snapshot.issues[1].body+=' ',c=>c.snapshot.retained_complete=false]){const next=structuredClone(c);mutate(next);assert.deepEqual(selected(run(next)),[]);assert.ok(codes(run(next)).includes('CHANGED_INPUT'));}});
test('shared completeness and local incompleteness never become zero inventory',()=>{for(const field of ['discovery_complete','retained_complete']){const c=fresh('S18');c.snapshot[field]=false;const r=run(c);assert.deepEqual(selected(r),[]);assert.ok(r.streams.every(s=>s.return_count===null));}const c=fresh('S18');c.snapshot.stream_checks[1].known_ids_complete=false;const r=run(c);assert.deepEqual(selected(r),['1001']);assert.equal(r.status,'partial');assert.equal(r.streams[1].return_count,null);});
test('three occupied native stages count malformed bodies; pending intents and unknown stages hold',()=>{for(const status of ['2','3','4']){const c=fresh('S11');c.snapshot.issues[2].status_id=status;c.snapshot.issues[2].body='broken';const r=run(c);assert.deepEqual(selected(r),[]);assert.deepEqual(r.streams[0].occupied_ids,['1002']);}const c=fresh('S01');c.snapshot.pending_intents=[{project_id:'100',label:'stream-1',ticket_id:'1001',attempt_id:'attempt'}];assert.ok(codes(run(c)).includes('PENDING_INTENT'));});
test('exact bound current completion alone accounts for repairs on every member',()=>{
 for(const id of ['repair-prerequisite-complete','repair-independent-complete','stack-independent-complete']){const c=fresh(id);assert.deepEqual(selected(run(c)),['1100']);
  for(const mutate of [c=>c.snapshot.completion_receipts=[],c=>c.snapshot.issues.at(-1).body+=' ',c=>c.snapshot.issues.at(-1).pointer.assignment.digest='sha256:'+'f'.repeat(64),c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.consumer='worker';c.snapshot.completion_receipts[0]=JSON.stringify(e);},c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.comment_pages[0].is_last=false;c.snapshot.completion_receipts[0]=JSON.stringify(e);},c=>c.snapshot.stream_checks[0].repair_inventory_complete=false,c=>c.snapshot.issues.at(-1).status_id='6']){const n=structuredClone(c);mutate(n);assert.deepEqual(selected(run(n)),[],id);}
 }
 const c=fresh('repair-independent-complete'),i=c.snapshot.issues.at(-1);c.snapshot.required_repairs=[{project_id:'100',label:'stream-1',ticket_id:i.id,reason:'required_request',references:structuredClone(i.required_requests)}];assert.deepEqual(selected(run(c)),['1100']);const n=structuredClone(c);n.snapshot.required_repairs[0].references[0].digest='sha256:'+'f'.repeat(64);assert.deepEqual(selected(run(n)),[]);assert.ok(run(n).streams.some(s=>s.reasons.some(r=>r.code==='LINEAGE_REQUIRED'&&r.path==='/required_repairs/0')));
 // A consistent newly declared but nonexistent obligation still fails the canonical chain.
 const extra=structuredClone(i.required_requests[0]);extra.record_id='00000000-0000-4000-8000-999999999999';i.required_requests.push(extra);const e=JSON.parse(c.snapshot.completion_receipts[0]);e.issues.find(x=>x.id===i.id).required_requests.push(extra);c.snapshot.completion_receipts[0]=JSON.stringify(e);assert.deepEqual(selected(run(c)),[]);
});
test('Human Review and accepted-later completion use exact native stage and all current requirements',()=>{for(const st of ['5','8']){const c=fresh('S06'),i=c.snapshot.issues.at(-1),e=JSON.parse(c.snapshot.completion_receipts[0]);i.status_id=st;e.issues[0].stage_id=st;c.snapshot.completion_receipts[0]=JSON.stringify(e);assert.deepEqual(selected(run(c)),['1100']);}for(const mutate of [c=>c.snapshot.issues.at(-1).status_id='10',c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.trusted.projects[0].actors.qa=['different'];c.snapshot.completion_receipts[0]=JSON.stringify(e);},c=>{const e=JSON.parse(c.snapshot.completion_receipts[0]);e.requirements[0].context_body+=' ';c.snapshot.completion_receipts[0]=JSON.stringify(e);}]){const c=fresh('S06');mutate(c);assert.deepEqual(selected(run(c)),[]);}});
test('structural and bounds failures produce no partial selections or raw diagnostics',()=>{const c=fresh('S01');for(const mutate of [c=>c.snapshot.issues.push(c.snapshot.issues[1]),c=>c.snapshot.projects.push(c.snapshot.projects[0]),c=>c.snapshot.issues[1]['SECRET-/key']='SECRET-BODY',c=>c.snapshot.stream_checks.push(c.snapshot.stream_checks[0]),c=>c.snapshot.schema='v2',c=>c.snapshot.issues[1].labels=Array(101).fill('x'),c=>c.snapshot.site='https://u:SECRET@jira.example.invalid']){const n=structuredClone(c);mutate(n);const r=run(n);assert.equal(r.valid,false);assert.deepEqual(r.streams,[]);assert.ok(!JSON.stringify(r).includes('SECRET'));}
 for(const raw of ['{"schema":"x","schema":"y"}','a: 1','{"x":9007199254740992}',new Uint8Array([0xc3,0x28]),'{"x":"\\ud800"}','{"a":'+JSON.stringify(Array(1001).fill(0))+'}'])assert.equal(previewSnapshot(JSON.stringify(c.config),raw).valid,false);
 const raw=JSON.stringify(c.snapshot),at=raw+' '.repeat(SNAPSHOT_LIMITS.bytes-Buffer.byteLength(raw));assert.equal(previewSnapshot(JSON.stringify(c.config),at).valid,true);assert.equal(previewSnapshot(JSON.stringify(c.config),at+' ').scope_diagnostics[0].code,'LIMIT');
 const many=structuredClone(c);many.config.projects=Array.from({length:101},(_,i)=>({...structuredClone(c.config.projects[0]),id:String(i)}));assert.equal(run(many).scope_diagnostics[0].code,'LIMIT');
});
test('raw finite floating literals retain canonical work parser provenance in YAML and ADF',()=>{for(const format of ['yaml','adf']){const c=fresh('S01'),i=c.snapshot.issues[1];const w=JSON.parse(i.body),ctx=JSON.parse(i.context_body);/* human-only contract has no arbitrary numeric slots; use allowed database parameter in mixed canonical fixture. */const mixed=JSON.parse(readFileSync(new URL('./fixtures/work-semantics.json',import.meta.url))).mixed;mixed.context.subject_key=i.key;mixed.context.prerequisite_graph=[{ticket:i.key,prerequisites:[]}];mixed.work.testing_strategy.cases[0].steps[2].database.parameters[0]=1e20;mixed.context.operations[2].contract.database.parameters[0]=1e20;const body=JSON.stringify(mixed.work).replaceAll('100000000000000000000','1e20');i.format=format;i.body=format==='yaml'?body:JSON.stringify({version:1,type:'doc',content:[{type:'codeBlock',attrs:{language:'yaml'},content:[{type:'text',text:body}]}]});i.context_body=JSON.stringify(mixed.context).replaceAll('100000000000000000000','1e20');assert.deepEqual(selected(run(c)),['1001']);}});
test('CLI is strict, finite, nonwriting and equivalent to the pure API',()=>{const temp=mkdtempSync(path.join(tmpdir(),'pgb-preview-')),cli=new URL('../scripts/manager-preview.mjs',import.meta.url);try{const c=fresh('S01'),config=path.join(temp,'config.json'),input=path.join(temp,'snapshot.json');writeFileSync(config,JSON.stringify(c.config));writeFileSync(input,JSON.stringify(c.snapshot));const before=readdirSync(temp).map(p=>[p,readFileSync(path.join(temp,p),'utf8')]);const args=[cli.pathname,'--config',config,'--input',input];assert.deepEqual(JSON.parse(execFileSync(process.execPath,[...args,'--json'],{cwd:temp,encoding:'utf8'})),run(c));const human=execFileSync(process.execPath,args,{cwd:temp,encoding:'utf8'});assert.match(human,/Local supplied snapshot only/);assert.match(human,/selected EX-2/);assert.deepEqual(readdirSync(temp).map(p=>[p,readFileSync(path.join(temp,p),'utf8')]),before);
 const failure=(child,code,ordinary)=>{assert.equal(child.status,2);const result=JSON.parse(child.stdout);assert.equal(result.schema,ordinary?'pigboard-manager-preview/v2':'pigboard-manager-preview/v1');if(ordinary){assert.equal(result.mode,'ordinary');assert.equal(result.proof_basis,'authenticated_recorded_handoffs');assert.equal(result.external_freshness,'not_evaluated');assert.equal(result.metadata_continuity,'supplied_prior_tuples_only');}else assert.equal(Object.hasOwn(result,'mode'),false);assert.equal(Object.hasOwn(result,'purpose'),false);assert.equal(Object.hasOwn(result,'trust_limitations'),false);assert.equal(result.valid,false);assert.equal(result.status,'invalid');assert.equal(result.validation_scope,'supplied_snapshot');for(const field of ['live_freshness','permission','destination_authority'])assert.equal(result[field],'not_evaluated');assert.equal(result.execution_authorized,false);assert.equal(result.writes,0);assert.equal(result.configuration_digest,null);assert.equal(result.snapshot_digest,null);assert.deepEqual(result.streams,[]);assert.equal(result.scope_diagnostics[0].code,code);};
 execFileSync('mkfifo',[path.join(temp,'fifo')]);
 const isolated=path.join(temp,'isolated');mkdirSync(isolated);cpSync(cli,path.join(isolated,'preview.mjs'));assert.equal(spawnSync(process.execPath,[path.join(isolated,'preview.mjs'),'--help','--json'],{encoding:'utf8'}).status,0);
 for(const ordinary of [false,true]){const mode=ordinary?['--mode','ordinary']:[],failureArgs=[cli.pathname,...mode,'--config',config,'--input',input];
  for(const extra of [['--input',input],['--unknown'],['stray'],['--expected-snapshot-digest','bad']])failure(spawnSync(process.execPath,[...failureArgs,...extra,'--json'],{encoding:'utf8'}),'USAGE',ordinary);
  for(const file of [temp,path.join(temp,'missing')])failure(spawnSync(process.execPath,[cli.pathname,...mode,'--config',config,'--input',file,'--json'],{encoding:'utf8'}),'INPUT',ordinary);
  failure(spawnSync(process.execPath,[cli.pathname,...mode,'--config',config,'--input',path.join(temp,'fifo'),'--json'],{encoding:'utf8',timeout:2000}),'INPUT',ordinary);
  failure(spawnSync(process.execPath,[path.join(isolated,'preview.mjs'),...mode,'--config',config,'--input',input,'--json'],{encoding:'utf8'}),'SETUP',ordinary);
 }
 failure(spawnSync(process.execPath,[cli.pathname,'--unknown','--mode','ordinary','--json'],{encoding:'utf8'}),'USAGE',false);
 failure(spawnSync(process.execPath,[cli.pathname,'--mode','unknown','--config',config,'--input',input,'--json'],{encoding:'utf8'}),'USAGE',false);
 }finally{rmSync(temp,{recursive:true,force:true});}});

test('counts depend on known native facts, independently of repair-inventory and ownership holds',()=>{for(const id of ['S30','S31','S32'])assert.ok(run(fresh(id)).streams.every(s=>s.counts_complete&&s.return_count===1));const c=fresh('S12');c.snapshot.stream_checks[0].repair_inventory_complete=false;const r=run(c);assert.equal(r.streams[0].decision,'hold');assert.equal(r.streams[0].return_count,5);c.snapshot.stream_checks[0].known_ids_complete=false;assert.equal(run(c).streams[0].return_count,null);});
test('known lost-label active child cannot vanish without a retained row; independent removals respect incoming obligations',()=>{const c=fresh('S01'),child=structuredClone(c.snapshot.issues[1]);child.id='1002';child.key='EX-3';child.labels=[];child.status_id='2';child.body=null;child.context_body=null;c.snapshot.issues.push(child);assert.deepEqual(selected(run(c)),[]);assert.ok(codes(run(c)).includes('MEMBERSHIP_MISMATCH'));const incoming=fresh('S05'),ep=JSON.parse(incoming.snapshot.issues[0].body);ep.workstreams[0].story_order=['EX-2'];incoming.snapshot.issues[0].body=JSON.stringify(ep);assert.deepEqual(selected(run(incoming)),[]);assert.ok(codes(run(incoming)).includes('MEMBERSHIP_MISMATCH'));});
