test('exact JSON format token survives malformed syntax without input opens and explicit --json filenames remain human',()=>{
 const dir=mkdtempSync(path.join(tmpdir(),'pgb-json-format-')),cli=new URL('../scripts/manager-preview.mjs',import.meta.url).pathname;try{
  const c=fresh('S01'),config=path.join(dir,'--json'),input=path.join(dir,'snapshot.json'),hook=path.join(dir,'audit-open.mjs');writeFileSync(config,JSON.stringify(c.config));writeFileSync(input,JSON.stringify(c.snapshot));writeFileSync(hook,"import fsp from 'node:fs/promises';import{syncBuiltinESMExports}from'node:module';let calls=0;fsp.open=async()=>{calls++;throw Error('AUDITED_INPUT_OPEN');};syncBuiltinESMExports();process.on('exit',()=>process.stderr.write('OPEN_ATTEMPTS='+calls+'\\n'));\n");const before=[readFileSync(config,'utf8'),readFileSync(input,'utf8')];
  const invoke=(args,audit=false)=>spawnSync(process.execPath,[...(audit?['--import',hook]:[]),cli,...args],{cwd:dir,encoding:'utf8',timeout:5000});
  const malformed=[];for(const flag of ['--config','--input','--expected-site','--expected-snapshot-digest'])malformed.push([flag,'--json'],['--json',flag]);malformed.push(['--unknown','SECRET_INPUT_NEVER_OPENED','--json'],['--json','--json'],['--config',config,'--config',config,'--json']);
  for(const args of malformed){const p=invoke(args,true),r=JSON.parse(p.stdout);assert.equal(p.status,2);assert.equal(p.stderr,'OPEN_ATTEMPTS=0\n');assert.equal(r.schema,'pigboard-manager-preview/v1');assert.equal(r.valid,false);assert.equal(r.status,'invalid');assert.equal(r.scope_diagnostics[0].code,'USAGE');assert.deepEqual(r.streams,[]);assert.equal(r.execution_authorized,false);assert.equal(r.writes,0);assert.ok(!p.stdout.includes('SECRET_INPUT'));assert.ok(!p.stdout.includes(dir));const normal=invoke(args);assert.equal(normal.stdout,p.stdout);assert.equal(normal.stderr,'');}
  for(const flag of ['--config','--input','--expected-site','--expected-snapshot-digest']){const p=invoke([flag],true);assert.equal(p.status,2);assert.equal(p.stderr,'OPEN_ATTEMPTS=0\n');assert.match(p.stdout,/USAGE/);assert.ok(!p.stdout.startsWith('{'));}
  for(const file of ['./--json',config]){const args=['--config',file,'--input',input],human=invoke(args),json=invoke([...args,'--json']);assert.equal(human.status,0);assert.match(human.stdout,/selected EX-2/);assert.ok(!human.stdout.startsWith('{'));assert.equal(human.stderr,'');assert.equal(json.status,0);assert.deepEqual(JSON.parse(json.stdout),run(c));}
  for(const args of [['--help'],['--help','--json']]){const p=invoke(args,true);assert.equal(p.status,0);assert.equal(p.stderr,'OPEN_ATTEMPTS=0\n');if(args.includes('--json'))assert.match(JSON.parse(p.stdout).help,/Preview ready work/);else assert.match(p.stdout,/Preview ready work/);}
  const observed=invoke(['--config',config,'--input',input,'--json'],true);assert.equal(observed.status,2);assert.equal(observed.stderr,'OPEN_ATTEMPTS=1\n');assert.equal(JSON.parse(observed.stdout).scope_diagnostics[0].code,'INPUT');assert.deepEqual([readFileSync(config,'utf8'),readFileSync(input,'utf8')],before);
 }finally{rmSync(dir,{recursive:true,force:true});}
});

